                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                        if 0<=nx<h and 0<=ny<w and grid[nx][ny]==2 and (nx,ny) not in seen: seen.add((nx,ny)); stack.append((nx,ny))
                comps.append(cells)
    # Demo identifies components in the zig-zag chain as 8: apply cells belonging to 2x2 blocks at top/bottom ends?
    for cells in comps:
        rr=[x for x,y in cells]; cc=[y for x,y in cells]
        if len(cells)==4 and max(rr)-min(rr)==1 and max(cc)-min(cc)==1:
            # tiles having top-left coordinate in the connected staircase sequence
            tl=(min(rr),min(cc))
            if tl in ((0,0),(0,11),(1,4),(1,7),(3,13),(5,6),(5,15)):
                for x,y in cells: out[x][y]=8
    return out
